using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class PrivateInformationTests
{
    internal static readonly EntityId Speaker=HistoricalHouseholdCatalog.Edition.People.Single().Id;
    internal static WorldSession Start(bool policy=true){var p=NewGameWorldTests.Officer(role:StartTemplate.Ronin,site:"site:kofu");var friend=p with{Id="created:private-friend"};var setup=NewGameSetup.Preview(NewGameWorld.Scenario(HistoricalStartCatalog.Current),new([p,friend],[]));Assert.True(setup.IsEligible(),string.Join(";",setup.Errors));return new(NewGameWorld.Create(setup.World!,[p,friend],p.Id,historicalCatalog:HistoricalStartCatalog.Current,npcRoutinePolicy:NewGameNpcRoutine.Policy,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,companionPolicy:PersonalCompanions.Policy,informationPolicy:policy?PrivateInformation.Policy:null));}
    static void Advance(WorldSession s,long at){while(s.Seconds<at){long old=s.Seconds;s.SetPaused(false);s.AdvanceTo(at,100000);Assert.True(s.Seconds>old);}}
    static CommandResult Act(WorldSession s,InformationAction action,EntityId? quote=null,string? id=null)=>s.ContactForInformation(new(new(id??"request:private/"+s.Revision),Speaker,action,quote),s.PlayerControl,s.Revision);
    static EntityId Ask(WorldSession s){var r=Act(s,InformationAction.Ask);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);return s.PrivateInformationView().Last().Quote;}
    static void Accept(WorldSession s,EntityId q){var r=Act(s,InformationAction.Accept,q);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);}
    static void Open(WorldSession s){var m=s.DiagnosticSnapshot().Messaging.Messages.Last(m=>m.Kind==PrivateInformation.Kind);Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,new(m.Id),s.Revision).Code);}
    [Fact]public void OnlyObservedInformationCanBeOfferedAndAskDoesNotSpendMoney(){var s=Start();var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Act(s,InformationAction.Ask).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));Advance(s,8);long money=NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl);Ask(s);Assert.Equal(money,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));Assert.Empty(BranchRoutes.KnownBlocked(s.DiagnosticSnapshot(),s.PlayerControl));Assert.DoesNotContain(s.DiagnosticSnapshot().Evidence,e=>e.Observer==s.PlayerControl&&e.Id.Value.StartsWith("evidence:private-info/"));}
    [Fact]public void SealedDeliveryOpeningAndPrivatePaymentAreSeparate(){var s=Start();Advance(s,8);var q=Ask(s);Accept(s,q);var w=s.DiagnosticSnapshot();Assert.DoesNotContain(w.Evidence,e=>e.Id.Value.StartsWith("evidence:private-info/"));Assert.Equal(1000,NewGameWork.Balance(w,s.PlayerControl));Assert.Equal(ResultCode.NotAvailable,Act(s,InformationAction.Pay,q).Code);Advance(s,9);Assert.DoesNotContain(s.DiagnosticSnapshot().Evidence,e=>e.Id.Value.StartsWith("evidence:private-info/"));Open(s);Assert.Contains(s.DiagnosticSnapshot().Evidence,e=>e.Observer==s.PlayerControl&&e.Id.Value.StartsWith("evidence:private-info/"));Assert.Equal(ResultCode.Accepted,Act(s,InformationAction.Pay,q).Code);w=s.DiagnosticSnapshot();Assert.Equal(980,NewGameWork.Balance(w,s.PlayerControl));Assert.Equal(1020,NewGameWork.Balance(w,Speaker));Assert.Equal(ResultCode.NotAvailable,Act(s,InformationAction.Pay,q).Code);}
    [Fact]public void DatedReportDoesNotUseCurrentSecretRoadTruth(){var s=Start();Advance(s,8);var w=s.DiagnosticSnapshot();var source=w.Evidence.First(e=>e.Observer==Speaker&&e.Claim.StartsWith("route-open:"));string edge=source.Claim[11..];w.Couriers=w.Couriers! with{Conditions=[..w.Couriers!.Conditions,new(w.ElapsedSeconds+1,edge,true)]};s=new WorldSession(w);Advance(s,10);var q=Ask(s);Accept(s,q);Advance(s,11);Open(s);w=s.DiagnosticSnapshot();var shared=w.Evidence.Single(e=>e.Observer==s.PlayerControl&&e.Message!=null&&e.Claim==source.Claim&&e.Id.Value.StartsWith("evidence:private-info/"));Assert.Equal(source.ObservedAt,shared.ObservedAt);Assert.Equal(11,shared.RecordedAt);Assert.True(RegionalCampaign.BlockedAt(w,edge,s.Seconds));Assert.DoesNotContain(edge,BranchRoutes.KnownBlocked(w,s.PlayerControl));}
    [Fact]public void PrivateContactDoesNotNotifyMasterOrChangeServiceAndTroops(){var s=Start();Advance(s,8);var w=s.DiagnosticSnapshot();var q=Ask(s);Accept(s,q);Advance(s,9);Open(s);var a=s.DiagnosticSnapshot();Assert.Equal(ContractJson.Write(w.Memberships),ContractJson.Write(a.Memberships));Assert.Equal(ContractJson.Write(w.ServiceBonds),ContractJson.Write(a.ServiceBonds));Assert.Equal(ContractJson.Write(w.Units),ContractJson.Write(a.Units));var mid=a.Messaging.Messages.Last(m=>m.Kind==PrivateInformation.Kind).Id;Assert.DoesNotContain(a.Messaging.Knowledge,k=>k.CharacterId=="person:shingen"&&k.MessageId==mid);Assert.DoesNotContain(a.Evidence,e=>e.Observer==new EntityId("person:shingen")&&e.Id.Value.StartsWith("evidence:private-info/"));}
    [Fact]public void WitnessedPaymentImprovesNextOfferOnlyForSameContact(){var s=Start();Advance(s,8);var q=Ask(s);Assert.Equal(20,s.PrivateInformationView().Last().Fee);Accept(s,q);Advance(s,9);Open(s);Assert.Equal(ResultCode.NotAvailable,Act(s,InformationAction.Ask).Code);Assert.Equal(ResultCode.Accepted,Act(s,InformationAction.Pay,q).Code);var next=Ask(s);Assert.NotEqual(q,next);Assert.Equal(15,s.PrivateInformationView().Last().Fee);}
    [Fact]public void StaleRevisionAndRepeatedIdDoNotDuplicatePaperOrCharges(){var s=Start();Advance(s,8);var i=new InformationInput(new("request:private-stable"),Speaker,InformationAction.Ask);Assert.Equal(ResultCode.StateChanged,s.ContactForInformation(i,s.PlayerControl,999).Code);Assert.Equal(ResultCode.Accepted,s.ContactForInformation(i,s.PlayerControl,s.Revision).Code);Assert.Equal(ResultCode.AlreadyAccepted,s.ContactForInformation(i,s.PlayerControl,s.Revision).Code);Assert.Equal(ResultCode.IdPayloadConflict,s.ContactForInformation(i with{Action=InformationAction.Pay},s.PlayerControl,s.Revision).Code);Assert.Single(s.PrivateInformationView());}
    [Fact]public void ForeignActorCannotReadOrPayForPlayerContact(){var s=Start();Advance(s,8);Assert.Equal(ResultCode.NotAvailable,s.ContactForInformation(new(new("request:other"),Speaker,InformationAction.Ask),Speaker,s.Revision).Code);}
    [Fact]public void AnotherSpeakerOrUnknownQuoteCannotAcceptOriginalTerms(){var s=Start();Advance(s,8);var q=Ask(s);Assert.Equal(ResultCode.NotAvailable,s.ContactForInformation(new(new("request:other-speaker"),new("person:shingen"),InformationAction.Accept,q),s.PlayerControl,s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,Act(s,InformationAction.Accept,new("request:unknown")).Code);}
    [Fact]public void LegacyNullPolicyKeepsInitialBytesAndRejectsStateInjection(){var s=Start(false);var bytes=ContractJson.Write(s.DiagnosticSnapshot());Assert.DoesNotContain("InformationPolicy",System.Text.Encoding.UTF8.GetString(bytes));Assert.Equal(bytes,ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(bytes)).DiagnosticSnapshot()));Assert.Equal(ResultCode.NotAvailable,Act(s,InformationAction.Ask).Code);var w=s.DiagnosticSnapshot();w.PrivateInformation=new(1,PrivateInformation.Policy,[],[],[]);Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void SourceFeeAndObservationDateTamperingAreRejected(){var s=Start();Advance(s,8);var q=Ask(s);var w=s.DiagnosticSnapshot();w.PrivateInformation=w.PrivateInformation! with{Quotes=[w.PrivateInformation.Quotes.Single() with{Fee=1}]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));Accept(s,q);Advance(s,9);Open(s);w=s.DiagnosticSnapshot();w.Evidence=w.Evidence.Select(e=>e.Id.Value.StartsWith("evidence:private-info/")?e with{ObservedAt=9}:e).ToArray();Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void ExistingOrderIdCannotBeReusedAsContactId(){var s=Start();Advance(s,8);var input=TravelWorld.Move(s.DiagnosticSnapshot(),"request:occupied-info","castle");Assert.Equal(ResultCode.Accepted,s.Submit(input,s.Revision).Code);Assert.Equal(ResultCode.IdPayloadConflict,Act(s,InformationAction.Ask,id:"request:occupied-info").Code);}
    [Fact]public void ActualSaveBeforeOpeningAndAfterPaymentContinuesWithSameKnownFactsAndMoney(){var s=Start();Advance(s,8);var q=Ask(s);Accept(s,q);s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"private-info-save-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(s,"sealed",w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("sealed"),host.Current,host.Current.Revision));var b=host.Current;Export(s,b,"info-sealed");Advance(s,9);Advance(b,9);Open(s);Open(b);Assert.Equal(ResultCode.Accepted,Act(s,InformationAction.Pay,q).Code);Assert.Equal(ResultCode.Accepted,Act(b,InformationAction.Pay,q).Code);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(b.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(s.PrivateInformationView()),ContractJson.Write(b.PrivateInformationView()));s.SetPaused(true);Assert.True(store.Save(s,"paid",w.WorldId).Published);var again=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,again.CommitLoad(store.Prepare("paid"),again.Current,again.Current.Revision));Export(s,again.Current,"info-paid");}

    static void Export(WorldSession a,WorldSession b,string name){var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(string.IsNullOrWhiteSpace(dir))return;Directory.CreateDirectory(dir);foreach(var row in new[]{(s:a,tag:"before"),(s:b,tag:"restored")})File.WriteAllBytes(Path.Combine(dir,name+"."+row.tag+".json"),ContractJson.Write(row.s.DiagnosticSnapshot()));}
    [Fact]public void LowPrivateFundsDoNotEraseOpenedInformationDebt(){var s=Start();Advance(s,8);var person=new EntityId("created:private-friend");Assert.Equal(ResultCode.Accepted,s.ManageCompanion(new(new("request:fee-companion"),person,CompanionAction.Agree,20),s.PlayerControl,s.Revision).Code);Advance(s,8+49*86400);Assert.Equal(ResultCode.Accepted,s.ManageCompanion(new(new("request:fee-companion-paid"),person,CompanionAction.Pay,980),s.PlayerControl,s.Revision).Code);Assert.Equal(0,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));var q=Ask(s);Accept(s,q);Advance(s,s.Seconds+1);Open(s);var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Act(s,InformationAction.Pay,q).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));Assert.Contains(s.PrivateInformationView(),c=>c.Quote==q&&c.Stage.Contains("未払い"));}
    [Fact]public void ActualDeparturePreventsRemotePaymentAndRevealsNoNewSpeakerState(){var s=Start();Advance(s,8);var q=Ask(s);Accept(s,q);Advance(s,9);Open(s);Assert.Equal(ResultCode.Accepted,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:information-away","castle"),s.Revision).Code);Advance(s,11);var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Act(s,InformationAction.Pay,q).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));Assert.False(s.PrivateInformationView().Single(c=>c.Quote==q).CanPay);}
    [Fact]public void FirsthandSourcesCannotBeReplacedWithMastersKnowledge(){var s=Start();Advance(s,8);Ask(s);var w=s.DiagnosticSnapshot();var other=w.Evidence.First(e=>e.Observer==new EntityId("person:shingen")&&e.Message==null&&e.Claim.StartsWith("route-open:"));var q=w.PrivateInformation!.Quotes.Single();w.PrivateInformation=w.PrivateInformation with{Quotes=[q with{Sources=[other.Id]}]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void OpenIdempotencyDoesNotDuplicateFactsOrDebt(){var s=Start();Advance(s,8);var q=Ask(s);Accept(s,q);Advance(s,9);Open(s);var w=s.DiagnosticSnapshot();var m=w.Messaging.Messages.Single(m=>m.Kind==PrivateInformation.Kind);Assert.Equal(ResultCode.AlreadyAccepted,s.Open(s.PlayerControl,new(m.Id),s.Revision).Code);Assert.Equal(ContractJson.Write(w),ContractJson.Write(s.DiagnosticSnapshot()));Assert.Equal(ResultCode.Accepted,Act(s,InformationAction.Pay,q).Code);Assert.Equal(980,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));}
    [Fact]public void NewProfilePinsPolicyAndOldProfileDoesNotAcquireIt(){var w=Start().DiagnosticSnapshot();var d=w.NewGame!;var store=new NewCampaignStore(Path.Combine(Path.GetTempPath(),"private-info-profile-"+Guid.NewGuid().ToString("N")));var p=store.New(d.Start,d.Registered,d.Selected.Value,d.Seed,historicalCatalog:d.HistoricalCatalog,inspectionPolicy:d.InspectionPolicy,workPolicy:d.WorkPolicy,informationPolicy:PrivateInformation.Policy);Assert.Equal(PrivateInformation.Policy,store.Read(p.Instance).InformationPolicy);Assert.NotNull(NewCampaignStore.Build(p).PrivateInformation);}
    [Fact]public void EachSuccessfulPaymentKeepsGlobalMoneyConstantAndChangesOnlyThisContactOffer(){var s=Start();Advance(s,8);long initial=s.DiagnosticSnapshot().ResourceLots.Where(l=>l.Kind=="money").Sum(l=>l.Quantity);var first=Ask(s);Accept(s,first);Advance(s,9);Open(s);Act(s,InformationAction.Pay,first);var second=Ask(s);Assert.Equal(15,s.PrivateInformationView().Last().Fee);Accept(s,second);Advance(s,10);Open(s);Assert.Equal(ResultCode.Accepted,Act(s,InformationAction.Pay,second).Code);Assert.Equal(965,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));Assert.Equal(initial,s.DiagnosticSnapshot().ResourceLots.Where(l=>l.Kind=="money").Sum(l=>l.Quantity));var other=s.ContactForInformation(new(new("request:other-info"),new("person:shingen"),InformationAction.Ask),s.PlayerControl,s.Revision);Assert.Equal(ResultCode.Accepted,other.Code);Assert.Equal(20,s.PrivateInformationView().Last().Fee);}
}
